}

if (registry_read_ok && cmdLower === '/start' && (role === 'admin' || role === 'moderator') && decision.identity && decision.identity.row) {
  access_registry_write = true;
  access_upsert = rehydrateReplyProfile(Object.assign({}, decision.identity.row, {
