// PHASE3G1_REPLY_PROFILES
function __iseoHandleReplyProfileCommands(parts, accessRows, actorRow, isAdmin) {
  const cmd = String(parts.command || '').trim();
  const args = parts.args || [];
  const rows = accessRows || [];
  function norm(s){ return String(s||'').trim().toLowerCase().replace(/^@/,''); }
  function findUser(token){
    const t=norm(token); if(!t) return null;
    return rows.find(r => norm(r.display_name)===t || norm(r.telegram_username)===t) || null;
  }
  function card(r){
    const name = String(r.reply_sender_name||'').trim() || '—';
    const en = (r.reply_sender_enabled===true || r.reply_sender_enabled==='true' || r.reply_sender_enabled===1 || r.reply_sender_enabled==='1');
    const role = String(r.role||'').toLowerCase();
    const status = String(r.status||'').toLowerCase();
    const roleRu = role==='admin'?'Админ':(role==='moderator'?'Модератор':role||'—');
    const statusRu = status==='active'?'Активен':(status==='revoked'?'Отозван':(status||'—'));
    const eligible = ((role==='admin'||role==='moderator') && status==='active') ? 'да' : 'нет';
    return ['Пользователь: '+(r.display_name||'—'),'Имя для клиента: '+name,'Персональный ответ: '+(en?'включён':'выключен'),'Роль: '+roleRu,'Статус доступа: '+statusRu,'Получатель карточек: '+eligible].join('\n');
  }
  function validName(raw){
    const name=String(raw||'').trim();
    if(!name || name.length<2 || name.length>32) return null;
    if(/@|https?:|\d{3,}|[<>{}]/.test(name)) return null;
    if(!/^[A-Za-zА-Яа-яЁё]+(?:[\-'][A-Za-zА-Яа-яЁё]+)?$/.test(name)) return null;
    return name;
  }
  if (cmd === '/my_reply_profile') {
    return { handled:true, reply: actorRow ? card(actorRow) : 'Профиль ответа не найден. Обратитесь к администратору.' };
  }
  if (cmd === '/reply_profiles') {
    if (!isAdmin) return { handled:true, reply: 'Доступ запрещён.' };
    const list = rows.filter(r => ['admin','moderator'].includes(String(r.role||'').toLowerCase()));
    const lines = ['Профили ответа клиенту',''];
    for (const r of list) {
      const en = (r.reply_sender_enabled===true || r.reply_sender_enabled==='true');
      lines.push('• '+(r.display_name||'—')+': '+(r.reply_sender_name||'—')+' · '+(en?'вкл':'выкл')+' · '+(r.status||'—'));
    }
    return { handled:true, reply: lines.join('\n') };
  }
  if (cmd === '/reply_profile') {
    if (!isAdmin) return { handled:true, reply: 'Доступ запрещён.' };
    const row = findUser(args[0]);
    if (!row) return { handled:true, reply: 'Пользователь не найден. Укажите имя из списка доступа.' };
    return { handled:true, reply: card(row) };
  }
  if (cmd === '/reply_name_set' || cmd === '/reply_name_enable' || cmd === '/reply_name_disable') {
    if (!isAdmin) return { handled:true, reply: 'Изменение имени для ответа доступно только администратору.' };
    const row = findUser(args[0]);
    if (!row) return { handled:true, reply: 'Пользователь не найден. Укажите имя из списка доступа.' };
    if (cmd === '/reply_name_set') {
      const nm = validName(args.slice(1).join(' '));
      if (!nm) return { handled:true, reply: 'Имя отклонено. Укажите обычное имя без фамилии, @, ссылок и эмодзи.' };
      return {
        handled:true,
        reply: 'Имя для клиента обновлено.\n\n'+card(Object.assign({}, row, { reply_sender_name:nm, reply_sender_enabled:true })),
        access_patch: {
          telegram_user_id: row.telegram_user_id,
          reply_sender_name: nm,
          reply_sender_enabled: true,
          reply_company_name: row.reply_company_name || 'INTLSEO',
          reply_profile_version: 'iseo-recipient-name-v1.0',
          reply_profile_updated_at: new Date().toISOString(),
          reply_profile_updated_by: 'admin',
        },
      };
    }
    const en = cmd === '/reply_name_enable';
    if (en && !String(row.reply_sender_name||'').trim()) {
      return { handled:true, reply: 'Сначала задайте корректное имя: /reply_name_set <пользователь> <имя>' };
    }
    return {
      handled:true,
      reply: card(Object.assign({}, row, { reply_sender_enabled: en })),
      access_patch: {
        telegram_user_id: row.telegram_user_id,
        reply_sender_enabled: en,
        reply_profile_version: 'iseo-recipient-name-v1.0',
        reply_profile_updated_at: new Date().toISOString(),
        reply_profile_updated_by: 'admin',
      },
    };
  }
  return { handled:false };
}

