  if (row.role === 'admin') {
    return { ok: false, reply: 'Нельзя отозвать права администратора командой модератора.' };
  }
  // protect last admin indirectly — moderator command cannot target admin
  if (row.role !== 'moderator' && row.status !== 'active') {
