function splitHelpHtml(full) {
  const markers = [
    '📋 Работа с заявками',
    '⏰ Напоминания',
    '👥 Пользователи',
  ];
  const idxs = markers.map((m) => full.indexOf(m)).filter((i) => i >= 0);
  if (idxs.length < 2) {
    // hard chunk
    const chunks = [];
    for (let i = 0; i < full.length; i += 3500) chunks.push(full.slice(i, i + 3500));
    return chunks.map((c, i) => c + '\n\n(' + (i + 1) + '/' + chunks.length + ')');
  }
  const a = full.slice(0, idxs[1]).trim();
  const bEnd = idxs.length >= 3 ? idxs[2] : full.length;
  const b = full.slice(idxs[1], bEnd).trim();
  const c = idxs.length >= 3 ? full.slice(idxs[2]).trim() : '';
  const parts = [a, b, c].filter(Boolean);
  return parts.map((p, i) => p + '\n\n(часть ' + (i + 1) + '/' + parts.length + ')');
}

