  if (parts.length >= 2 && /^p\d+$/i.test(parts[parts.length - 1])) {
    page = Math.max(1, parseInt(parts[parts.length - 1].slice(1), 10) || 1);
    parts.pop();
  }
  const filterToken = parts.join(':');
  function fnvTok(s) {
    const str = String(s || '');
    let h1 = 0x811c9dc5 >>> 0;
    for (let i = 0; i < str.length; i++) { h1 ^= str.charCodeAt(i); h1 = Math.imul(h1, 0x01000193); }
    let h2 = 0x9e3779b9 >>> 0;
    for (let i = 0; i < str.length; i++) { h2 ^= str.charCodeAt(i); h2 = Math.imul(h2, 0x85ebca6b); h2 = (h2 << 13) | (h2 >>> 19); }
    return ((h1 >>> 0).toString(16).padStart(8, '0') + (h2 >>> 0).toString(16).padStart(8, '0')).slice(0, 12);
  }
  function mapCat(L) {
    const raw = [L.resolved_service_label, L.resolved_service, L.service_type, L.service, L.interest, L.category].map((v) => String(v || '').trim()).filter(Boolean).join(' | ');
    const s = raw.toLowerCase();
    if (!s) return 'Требует уточнения';
    if (/требует уточнен|needs.?clarif|unknown|неизвестно|уточн/.test(s)) return 'Требует уточнения';
    if (/аудит|audit/.test(s)) return 'Аудит';
    if (/\bseo\b|сео|поисков/.test(s)) return 'SEO';
    if (/реклам|ads?|direct|директ|context|яндекс|google ads|ppc/.test(s)) return 'Реклама';
    if (/сайт|website|web.?dev|разработк|landing|лендинг/.test(s)) return 'Разработка сайта';
    if (/^other$|другое|прочее|misc/.test(s)) return 'Другое';
    return 'Требует уточнения';
  }
  function labelOf(L) {
    const name = String(L.client_name || '').trim();
    if (name && !/^(unknown|n\/a|—|-)$/i.test(name)) return name.slice(0, 40);
    const site = String(L.site || '').trim().replace(/^https?:\/\//i, '').split('/')[0];
    if (site && site.includes('.')) return site.slice(0, 40);
    return 'Лид без имени';
  }
  function ageDaysOf(L) {
    let ts = null;
    for (const c of [L.lead_received_at, L.received_at, L.created_at]) {
      const d = c ? new Date(c) : null;
      if (d && !Number.isNaN(d.getTime())) { ts = d.getTime(); break; }
    }
    if (ts == null) return { days: null, sort: Number.MAX_SAFE_INTEGER, text: 'возраст неизвестен' };
    const days = Math.max(0, Math.floor((Date.now() - ts) / 86400000));
    let unit = 'дней'; const mod10 = days % 10, mod100 = days % 100;
    if (days === 0) return { days, sort: ts, text: 'сегодня' };
    if (mod10 === 1 && mod100 !== 11) unit = 'день';
    else if (mod10 >= 2 && mod10 <= 4 && !(mod100 >= 12 && mod100 <= 14)) unit = 'дня';
    return { days, sort: ts, text: days + ' ' + unit };
