      return ACK.reopen;
    }
    if (newStatus === 'spam' || eventType === 'manager_marked_spam') return ACK.spam;
    if (newStatus === 'processed' || eventType === 'manager_marked_processed') return ACK.processed;
    return String(h.answer_text || 'OK');
