}

function findAccessRow(rows, userId) {
  const uid = String(userId || '');
  if (!uid) return null;
  const list = (rows || []).map(rowFromSheet).filter((r) => r.telegram_user_id);
  return list.find((r) => r.telegram_user_id === uid) || null;
