function findByAccessCode(rows, code) {
  const c = String(code || '').trim().toUpperCase();
  if (!c) return null;
  const list = (rows || []).map(rowFromSheet).filter((r) => r.telegram_user_id);
  return list.find((r) => accessCode(r.telegram_user_id) === c) || null;
}

