        if (mod10 === 1 && mod100 !== 11) u = 'день';
        else if (mod10 >= 2 && mod10 <= 4 && !(mod100 >= 12 && mod100 <= 14)) u = 'дня';
        age_text = d + ' ' + u;
      }
    }
    const marker = (!unk && d >= 5) ? '🔴' : ((!unk && d >= 3) ? '⚠️' : '');
    const label = (() => {
      const name = String(r.client_name || '').trim();
      if (name && !/^(unknown|n\/a|—|-)$/i.test(name)) return name.slice(0, 40);
      const site = String(r.site || '').trim().replace(/^https?:\/\//i, '').split('/')[0];
      if (site && site.includes('.')) return site.slice(0, 40);
      return 'Лид без имени';
    })();
    const catRaw = String(r.resolved_service_label || r.service || '').toLowerCase();
    let category = 'Требует уточнения';
    if (/аудит|audit/.test(catRaw)) category = 'Аудит';
    else if (/seo|сео/.test(catRaw)) category = 'SEO';
    else if (/реклам|direct|директ|ads/.test(catRaw)) category = 'Реклама';
    else if (/сайт|website|разработк/.test(catRaw)) category = 'Разработка сайта';
    else if (/other|другое/.test(catRaw)) category = 'Другое';
    return { sample: r, token: fnvTok(String(r.lead_id || '')), category, label, age_days: ageDays, age_text, marker, sort_ts: ts == null ? Number.MAX_SAFE_INTEGER : ts };
  }).sort((a, b) => a.sort_ts - b.sort_ts);
  const total = leads.length;
  const today = leads.filter((x) => x.age_days === 0).length;
  const older = leads.filter((x) => x.age_days != null && x.age_days >= 1).length;
  const cap = 25;
  const show = leads.slice(0, cap);
  show.forEach((e, i) => { e.idx = 'A' + (i + 1); });
  const order = ['Аудит','SEO','Реклама','Разработка сайта','Другое','Требует уточнения'];
  const icons = {'Аудит':'🔍','SEO':'📈','Реклама':'📣','Разработка сайта':'🌐','Другое':'📦','Требует уточнения':'❓'};
  const lines = ['🔔 Необработанные лиды — ' + total, '', 'На тест (ADMIN_A only)', total ? ('Самый старый: ' + (show[0] && show[0].age_text)) : '', ''];
  for (const cat of order) {
    const items = leads.filter((x) => x.category === cat);
    if (!items.length) continue;
    lines.push((icons[cat] || '•') + ' ' + cat + ' — ' + items.length);
    for (const it of items.filter((x) => x.idx)) {
      lines.push('• ' + it.idx + ' · ' + it.label + ' · ' + (it.marker ? it.marker + ' ' : '') + it.age_text);
    }
    const hid = items.length - items.filter((x) => x.idx).length;
    if (hid > 0) lines.push('… ещё ' + hid);
    lines.push('');
  }
  lines.push('Всего: ' + total + ' · сегодня: ' + today + ' · старше суток: ' + older);
  lines.push('');
  lines.push('⚠️ TEST — production claims/last_window не изменялись.');
  const rows = show.filter((x) => x.token).map((b) => ({
    row: { buttons: [{ text: (b.idx + ' ' + (b.label === 'Лид без имени' ? 'Без имени' : b.label)).slice(0, 28), additionalFields: { callback_data: 'sm:q:' + b.token } }] },
  }));
  return [{ json: {
    ...j,
    chat_id: String(j.chat_id || j.user_id || ''),
    reply_text: lines.filter((x, i, a) => !(x === '' && a[i - 1] === '')).join('\n').trim(),
    parse_mode: 'HTML',
    telegram_has_buttons: rows.length > 0,
    telegram_inline_keyboard_ui: { rows },
    reminder_digest_test: true,
    production_claim_pollution: false,
  } }];
}

if (cmd === '/pending_count') {
  let text;
  if (view.total === 0) {
    text = 'Необработанных заявок сейчас нет.';
  } else {
    const lines = ['Необработанных заявок: ' + view.total];
    const parts = [];
    if (view.buckets.under_2h) parts.push('до 2 часов: ' + view.buckets.under_2h);
    if (view.buckets.from_2h_to_24h) parts.push('2–24 часа: ' + view.buckets.from_2h_to_24h);
    if (view.buckets.over_24h) parts.push('старше суток: ' + view.buckets.over_24h);
    if (parts.length) lines.push(parts.join(' · '));
    text = lines.join('\n');
  }
  if (role === 'admin' && testCount > 0) text += '\nТестовых заявок: ' + testCount;
  return [{ json: { ...j, reply_text: text, parse_mode: 'HTML', pending_total: view.total } }];
}

// list
let page = 1;
for (const tok of args) {
  if (/^test$/i.test(tok)) continue;
  if (/^\d+$/.test(tok)) page = Number(tok);
  else {
    return [{ json: { ...j, reply_text: 'Использование: /pending_leads или /pending_leads 2', parse_mode: 'HTML' } }];
  }
}
const size = 5;
const pageCount = Math.max(1, Math.ceil(view.total / size) || 1);
if (!Number.isFinite(page) || page < 1) page = 1;
if (page > pageCount) page = pageCount;
if (view.total === 0) {
  return [{ json: { ...j, reply_text: 'Необработанных заявок сейчас нет.', parse_mode: 'HTML', pending_total: 0 } }];
}
const start = (page - 1) * size;
const slice = view.items.slice(start, start + size);
const lines = [];
slice.forEach((it, idx) => {
  const n = start + idx + 1;
  lines.push(n + '. ' + esc(it.age_display) + ' · ' + esc(it.client_display_name));
  lines.push(esc(it.resolved_service_label) + ' · ' + esc(it.website_summary));
  lines.push(esc(it.request_summary));
  lines.push(it.first_reply_ready ? 'Черновик ответа: готов' : 'Черновик ответа: нет');
  lines.push('');
});
lines.push('Страница ' + page + ' из ' + pageCount + ' · всего ' + view.total);
return [{ json: { ...j, reply_text: lines.join('\n').trim(), parse_mode: 'HTML', pending_total: view.total } }];

// Phase 3H.8.2.2 — Reminder Commands + current-state selector counters
// Phase 3H.8.2 — Reminder Commands quota ERROR visibility + Phase 3H.8 observability v1.1 + Phase 3H.6: live ACCESS recipient count + Phase 3H.4 syntax repair.
// Phase 3H.4 — Reminder Commands repair (syntax + truthful status text).
// Emits reply_text and optional single config_write for Prepare Config Write path.
// Never throws to Telegram silence: all paths return reply_text.

const j = $input.first().json;
const cmd = String(j.command || '').toLowerCase();
const args = Array.isArray(j.args) ? j.args.map((a) => String(a).trim()).filter(Boolean) : [];
const role = String(j.auth_role || '').toLowerCase();
const map = j.config_map || {};

function esc(s) {
  return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function validTime(s) {
  return /^([01]\d|2[0-3]):([0-5]\d)$/.test(String(s || '').trim());
}
function validTz(tz) {
  const t = String(tz || '').trim();
  if (!t) return false;
  try {
    Intl.DateTimeFormat('en-US', { timeZone: t }).format(new Date());
    return true;
  } catch (e) {
    return false;
  }
}

function formatMoscow(v) {
  const s = String(v || '').trim();
  if (!s) return '';
  const d = new Date(s);
  if (Number.isNaN(d.getTime())) return '';
  const parts = new Intl.DateTimeFormat('ru-RU', {
    timeZone: 'Europe/Moscow',
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
  }).formatToParts(d);
  const get = (t) => parts.find((p) => p.type === t)?.value || '';
  return `${get('day')}.${get('month')}.${get('year')} ${get('hour')}:${get('minute')} МСК`;
}

function ynExcluded(flag, defaultExcluded) {
  const raw = map[flag];
  if (raw === undefined || raw === null || String(raw).trim() === '') {
    return defaultExcluded ? 'исключены' : 'не подтверждено';
  }
  const on = String(raw).toLowerCase() === 'true';
  // include_tests=true means tests are included; display "исключены" when false
  if (flag === 'pending_reminder_include_tests') return on ? 'включены' : 'исключены';
  if (flag === 'pending_reminder_include_archive') return on ? 'включены' : 'исключены';
  return on ? 'да' : 'нет';
}

function countActiveRecipients() {
  // Phase 3H.6 — prefer live ACCESS_CONTROL (same staff predicate as Reminder Build Claims).
  // Falls back to CONFIG cache only if ACCESS read is unavailable in this execution.
  try {
    const accessRows = $('Read ACCESS_CONTROL').all().map((i) => i.json).filter((r) => r && typeof r === 'object' && !r.error);
    const seen = new Set();
    let n = 0;
    for (const r of accessRows) {
      const role = String(r.role || '').toLowerCase();
      const status = String(r.status || '').toLowerCase();
      if (status !== 'active') continue;
      if (role !== 'admin' && role !== 'moderator') continue;
      const chat = String(r.telegram_user_id || '').trim();
      if (!chat) continue;
      const ref = String(r.telegram_user_hash || '').trim() || ('r:' + chat.slice(-4));
      if (seen.has(ref)) continue;
      seen.add(ref);
      n += 1;
    }
    if (n > 0) return String(n);
  } catch (e) {
    // fall through to CONFIG cache
  }
  const fromCfg = map.pending_reminder_active_recipients_count || map.active_recipients_count;
  if (fromCfg !== undefined && String(fromCfg).trim() !== '') return String(fromCfg);
  return 'не подтверждено';
}

function statusText(moderatorShort) {
  const enabledRaw = map.pending_reminders_enabled;
  const enabledKnown = !(enabledRaw === undefined || enabledRaw === null || String(enabledRaw).trim() === '');
  const enabled = String(enabledRaw || '').toLowerCase() === 'true';
  const time = map.pending_reminder_time || 'не подтверждено';
  const tz = map.pending_reminder_timezone || 'не подтверждено';
  const min = map.pending_reminder_min_count || 'не подтверждено';
  const testsLine = ynExcluded('pending_reminder_include_tests', true);
  const archiveLine = ynExcluded('pending_reminder_include_archive', true);
  const once = String(map.pending_reminder_once_per_business_date || 'true').toLowerCase() !== 'false';

  const lastCheck =
    formatMoscow(map.pending_reminder_last_check_at) ||
    formatMoscow(map.pending_reminder_last_window) ||
    'не подтверждено';
  const lastSendRaw = map.pending_reminder_last_success_at;
  const lastSend = lastSendRaw && String(lastSendRaw).trim()
    ? (formatMoscow(lastSendRaw) || String(lastSendRaw))
    : 'не было';

  if (moderatorShort) {
    return [
      '⏰ Напоминания о необработанных лидах',
      '',
      'Напоминания: ' + (enabledKnown ? (enabled ? 'включены' : 'выключены') : 'не подтверждено'),
      'Расписание: Пн–Пт, ' + time + (tz === 'Europe/Moscow' ? ' МСК' : (' (' + tz + ')')),
      'Время: ' + time,
      'Часовой пояс: ' + tz,
      'Тестовые заявки: ' + testsLine,
      'Архивные записи: ' + archiveLine,
    ].join('\n');
  }

  const lastEval = formatMoscow(map.pending_reminder_last_evaluation_at) || 'не подтверждено';
  const rawDecision = String(map.pending_reminder_last_decision || '').trim();
  let lastDecision = rawDecision || 'не подтверждено';
  if (rawDecision === 'ERROR' || rawDecision === 'ERROR_SHEETS_429_ACCESS' || rawDecision === 'ERROR_CURRENT_STATE_RESOLUTION' || /^ERROR/.test(rawDecision)) lastDecision = 'Ошибка';
  else if (rawDecision === 'SENT') lastDecision = 'Отправлено';
  else if (rawDecision === 'SKIPPED_ZERO_PENDING') lastDecision = 'Пропуск (нет заявок)';
  else if (rawDecision === 'SKIPPED_ALREADY_SENT') lastDecision = 'Уже отправлено';
  else if (rawDecision === 'SKIPPED_OUTSIDE_WINDOW') lastDecision = 'Вне окна';
  const lastPending = (map.pending_reminder_last_pending_count != null && String(map.pending_reminder_last_pending_count).trim() !== '')
    ? String(map.pending_reminder_last_pending_count)
    : 'не подтверждено';
  const lastRaw = (map.pending_reminder_last_raw_candidate_rows != null && String(map.pending_reminder_last_raw_candidate_rows).trim() !== '')
    ? String(map.pending_reminder_last_raw_candidate_rows)
    : '';
  const lastUnique = (map.pending_reminder_last_unique_candidate_leads != null && String(map.pending_reminder_last_unique_candidate_leads).trim() !== '')
    ? String(map.pending_reminder_last_unique_candidate_leads)
    : '';
  const lastSafeUnknown = (map.pending_reminder_last_safe_unknown_count != null && String(map.pending_reminder_last_safe_unknown_count).trim() !== '')
    ? String(map.pending_reminder_last_safe_unknown_count)
    : '';
  const lastRecipients = (map.pending_reminder_last_recipient_count != null && String(map.pending_reminder_last_recipient_count).trim() !== '')
    ? String(map.pending_reminder_last_recipient_count)
    : 'не подтверждено';
  const lastErr = String(map.pending_reminder_last_error_safe || '').trim();

  const lines = [
    '⏰ Напоминания о необработанных лидах',
    '',
    'Напоминания: ' + (enabledKnown ? (enabled ? 'включены' : 'выключены') : 'не подтверждено'),
    'Расписание: Пн–Пт, ' + time + (tz === 'Europe/Moscow' ? ' МСК' : (' (' + tz + ')')),
    'Время: ' + time,
    'Часовой пояс: ' + tz,
    'Минимум необработанных заявок: ' + min,
    'Тестовые заявки: ' + testsLine,
    'Архивные записи: ' + archiveLine,
    'Получателей: ' + countActiveRecipients(),
    'Повторная отправка в течение дня: ' + (once ? 'исключена' : 'разрешена'),
    'Последняя оценка: ' + lastEval,
    'Необработанных сейчас: ' + lastPending,
  ];
  if (lastRaw !== '') lines.push('Строк-кандидатов: ' + lastRaw);
  if (lastUnique !== '') lines.push('Уникальных лидов: ' + lastUnique);
  if (lastSafeUnknown !== '') lines.push('SAFE_UNKNOWN: ' + lastSafeUnknown);
  const lastDelivered = String(map.pending_reminder_last_delivered_count || '').trim();
  const lastExpected = String(map.pending_reminder_last_expected_recipients || map.pending_reminder_active_recipients_count || '').trim();
  lines.push(
    'Последнее решение: ' + lastDecision,
    'Последняя проверка: ' + lastCheck,
    'Последняя отправка: ' + lastSend,
    'Получателей при последней отправке: ' + lastRecipients,
  );
  if (lastDelivered !== '' || lastExpected !== '') {
    lines.push('Доставка: ' + (lastDelivered || '—') + '/' + (lastExpected || '—'));
  }
  if (rawDecision === 'ERROR' || rawDecision === 'ERROR_SHEETS_429_ACCESS' || rawDecision === 'ERROR_CURRENT_STATE_RESOLUTION' || /^ERROR/.test(String(map.pending_reminder_last_decision || ''))) {
    const stage = String(map.pending_reminder_last_error_stage || '').trim() || 'не подтверждено';
    const retries = String(map.pending_reminder_last_retry_attempts || '').trim();
    const reason = String(map.pending_reminder_last_error_safe || lastErr || 'ошибка чтения таблицы');
    lines.push('Этап: ' + stage);
    lines.push('Причина: ' + reason);
    if (retries !== '') lines.push('Повторные попытки: ' + retries);
  } else if (lastErr) {
    lines.push('Активная ошибка: ' + lastErr);
  }
  return lines.join('\n');
}

function write(key, value, description) {
  return {
    key,
    value: String(value),
    type: 'string',
    updated_at: new Date().toISOString(),
    updated_by: 'admin_telegram',
    description: description || '',
  };
}

try {
  if (cmd === '/reminder_status') {
    return [{ json: { ...j, reply_text: statusText(role !== 'admin'), parse_mode: 'HTML', config_write: null } }];
  }

  if (role !== 'admin') {
    return [{ json: {
      ...j,
      reply_text: 'Изменять настройки напоминаний может только администратор.\nСмотреть статус: /reminder_status',
      parse_mode: 'HTML',
      config_write: null,
    } }];
  }

  if (cmd === '/reminder_on') {
    return [{ json: {
      ...j,
      reply_text: 'Ежедневные напоминания включены.\nВремя: ' + (map.pending_reminder_time || '10:00') + ' (' + (map.pending_reminder_timezone || 'Europe/Moscow') + ')',
      parse_mode: 'HTML',
      config_write: write('pending_reminders_enabled', 'true', 'Phase 3F.1 reminder enable'),
