        parse_mode: 'HTML',
        config_write: null,
      } }];
    }
    return [{ json: {
      ...j,
      reply_text: 'Минимум необработанных заявок для напоминания: ' + n,
      parse_mode: 'HTML',
      config_write: write('pending_reminder_min_count', String(n), 'Phase 3F.1 reminder min count'),
    } }];
  }

  return [{ json: { ...j, reply_text: 'Неизвестная команда напоминаний.', parse_mode: 'HTML', config_write: null } }];
} catch (e) {
  return [{ json: {
    ...j,
    reply_text: 'Не удалось сформировать ответ команды. Ошибка зафиксирована, повторите позже.',
    parse_mode: 'HTML',
    config_write: null,
    command_response_guard: 'runtime_exception',
    error_node: 'Reminder Commands',
    deny_reason: 'processing_failure',
  } }];
}

// Phase 3F.1 — Reminder Schedule Gate (schedule trigger entry).
// Fail-closed early exits. No Telegram path contamination.

const rows = $input.all().map((i) => i.json).filter((r) => r && typeof r === 'object');
// CONFIG rows arrive as key/value from Read Reminder CONFIG
const map = {};
for (const r of rows) {
  if (r.key != null) map[String(r.key)] = String(r.value ?? '');
}

const enabled = String(map.pending_reminders_enabled || '').toLowerCase() === 'true';
if (!enabled) {
  return [{ json: { reminder_proceed: false, reminder_skip_reason: 'disabled', config_map: map } }];
}

function validTime(s) { return /^([01]\d|2[0-3]):([0-5]\d)$/.test(String(s || '').trim()); }
function validTz(tz) {
  try { Intl.DateTimeFormat('en-US', { timeZone: String(tz) }).format(new Date()); return true; }
  catch (e) { return false; }
}

const time = map.pending_reminder_time || '10:00';
const tz = map.pending_reminder_timezone || 'Europe/Moscow';
if (!validTime(time) || !validTz(tz)) {
  return [{ json: { reminder_proceed: false, reminder_skip_reason: 'invalid_config', config_map: map } }];
}

const now = new Date();
const fmt = new Intl.DateTimeFormat('en-CA', {
  timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit', hourCycle: 'h23',
});
const parts = Object.fromEntries(fmt.formatToParts(now).filter((p) => p.type !== 'literal').map((p) => [p.type, p.value]));
const localDate = parts.year + '-' + parts.month + '-' + parts.day;
const weekdayShort = new Intl.DateTimeFormat('en-US', { timeZone: tz, weekday: 'short' }).format(now);
const isWeekday = weekdayShort === 'Mon' || weekdayShort === 'Tue' || weekdayShort === 'Wed' || weekdayShort === 'Thu' || weekdayShort === 'Fri';
if (!isWeekday) {
  return [{ json: {
    reminder_proceed: false,
    reminder_skip_reason: 'weekend_or_non_weekday',
    reminder_decision_hint: 'SKIPPED_WEEKEND',
    local_date: localDate,
    local_weekday: weekdayShort,
    config_map: map,
  } }];
}
const nowMins = Number(parts.hour) * 60 + Number(parts.minute);
const [th, tm] = time.split(':').map(Number);
const targetMins = th * 60 + tm;
const windowMinutes = 20;
if (nowMins < targetMins || nowMins >= targetMins + windowMinutes) {
  return [{ json: {
    reminder_proceed: false,
    reminder_skip_reason: 'outside_window',
    config_map: map,
    local_date: localDate,
  } }];
}

const windowKey = 'pending-reminder:' + localDate + ':' + time + ':' + tz;
if (String(map.pending_reminder_last_window || '') === windowKey) {
  return [{ json: {
    reminder_proceed: false,
    reminder_skip_reason: 'already_completed',
    reminder_window: windowKey,
    config_map: map,
  } }];
}

return [{ json: {
  reminder_proceed: true,
  reminder_skip_reason: '',
  reminder_window: windowKey,
  reminder_time: time,
  reminder_timezone: tz,
  local_date: localDate,
  config_map: map,
  pending_reminder_min_count: Number(map.pending_reminder_min_count || 1) || 1,
  pending_reminder_include_tests: String(map.pending_reminder_include_tests || 'false') === 'true',
