}
function validName(raw) {
  const name = String(raw ?? '').trim();
  if (!name || /\r|\n/.test(String(raw ?? ''))) return null;
  if (name.length < 2 || name.length > 32) return null;
  if (/@|https?:|www\.|\d{3,}|[<>{}[\]\\|^=+#*$%~`.,;:!?]|[\u{1F300}-\u{1FAFF}]/u.test(name)) return null;
  if (!/^[A-Za-zА-Яа-яЁё]+(?:[\-'][A-Za-zА-Яа-яЁё]+)?$/.test(name)) return null;
  if (/\s/.test(name)) return null;
