function profileList(pageArg) {
  const list = rows
    .filter(r => ['admin', 'moderator'].includes(String(r.role || '').toLowerCase()))
    .slice()
    .sort((a, b) => {
      const na = getNum(a) ?? 1e9;
      const nb = getNum(b) ?? 1e9;
