/**
 * Legacy source quality gate for 📄 Исходная заявка.
 * READ-only decision. No lifecycle mutation.
 */
function classifyLegacySourceQuality(rawRow, lead) {
  const row = rawRow && typeof rawRow === 'object' ? rawRow : {};
  const full = String(row.source_body_full || '').trim();
  const raw = String(row.raw_text || '').trim();
  const body = full || raw;
  const msgId = String(lead.source_message_id || row.gmail_message_id || '').trim();
  const parser = String(row.parser_version || lead.parser_version || '');
  if (full && /\n/.test(full) && full.length > 250) {
    return { quality: 'FULL_SOURCE_AVAILABLE', need_gmail_fallback: false, reason: 'source_body_full' };
  }
  if (!body) {
    return { quality: 'SOURCE_MISSING', need_gmail_fallback: Boolean(msgId), reason: 'empty_body', gmail_get_id: msgId };
  }
  const oneLine = !/\n/.test(body);
  const formish = /(?:От\s*кого|Способ\s*связи|Комментарий)\s*[:：]/i.test(body);
  const missingPage = !/Отправлено\s+со\s+страницы/i.test(body);
  const truncTail = /t\.me\s*$/i.test(body) || /тг\s+t\.me\s*$/i.test(body);
  const knownFlatParser = /sm-parser-v3\.3/i.test(parser);
  if (oneLine && formish && (missingPage || truncTail || body.length < 450) && msgId && (knownFlatParser || truncTail || missingPage)) {
    return { quality: 'LEGACY_RAW_LOSSY', need_gmail_fallback: true, reason: 'one_line_form_lossy', gmail_get_id: msgId };
  }
  if (body.length >= 40) {
    return { quality: 'LEGACY_RAW_GOOD_ENOUGH', need_gmail_fallback: false, reason: 'legacy_ok' };
  }
  return { quality: 'SOURCE_MISSING', need_gmail_fallback: Boolean(msgId), reason: 'too_short', gmail_get_id: msgId };
}

