function normalizeSpaces(raw) {
  return String(raw ?? '').replace(/\u00a0/g, ' ').replace(/[\u2007\u202F\u2009\u200A]/g, ' ').replace(/\r\n/g, '\n').replace(/\r/g, '\n');
}
function htmlToPlainText(html) {
  let s = String(html ?? '');
  if (!/<[a-z][\s\S]*>/i.test(s)) return normalizeSpaces(s);
  s = s.replace(/<script\b[\s\S]*?<\/script>/gi, ' ');
  s = s.replace(/<style\b[\s\S]*?<\/style>/gi, ' ');
  s = s.replace(/<head\b[\s\S]*?<\/head>/gi, ' ');
  s = s.replace(/<!--[\s\S]*?-->/g, ' ');
  s = s.replace(/<img\b[^>]*>/gi, ' ');
  s = s.replace(/<\s*br\s*\/?\s*>/gi, '\n');
  s = s.replace(/<hr\b[^>]*>/gi, '\n');
  s = s.replace(/<\/\s*(p|div|tr|li|h[1-6]|blockquote|section|article|header|footer|table)\s*>/gi, '\n');
  s = s.replace(/<\s*(p|div|tr|li|h[1-6]|blockquote|section|article|header|footer)\b[^>]*>/gi, '\n');
  s = s.replace(/<a[^>]+href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi, (_, href, text) => {
    const t = String(text).replace(/<[^>]+>/g, '').trim();
    if (t && t.length >= 3) return t;
    return href;
  });
  s = s.replace(/<[^>]+>/g, ' ');
  s = s.replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/&lt;/gi, '<').replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"').replace(/&#39;/gi, "'");
  s = normalizeSpaces(s).replace(/[^\S\n]{2,}/g, ' ').replace(/\n{4,}/g, '\n\n\n');
  return s.trim();
}
function capture(j) {
  const textPlain = String(j.textPlain || '').trim();
  const text = String(j.text || '').trim();
  const html = String(j.html || '').trim();
  const snippet = String(j.snippet || '').trim();
  if (textPlain && textPlain !== snippet) return { body: normalizeSpaces(textPlain), kind: 'textPlain' };
  if (html) return { body: htmlToPlainText(html), kind: 'html' };
  if (text && text !== snippet) {
    if (/<[a-z][\s\S]*>/i.test(text)) return { body: htmlToPlainText(text), kind: 'text_html' };
    return { body: normalizeSpaces(text), kind: 'text' };
  }
  if (html) return { body: htmlToPlainText(html), kind: 'html' };
  if (text) return { body: normalizeSpaces(text), kind: 'text' };
  return { body: snippet, kind: 'snippet' };
}

const prev = (() => { try { return $('Decide Gmail Source Fallback').first().json || {}; } catch (e) { return {}; } })();
